/** Read the closed language preference cookie. Unknown values safely use English. */
export function localeOf(cookie, acceptLanguage) {
  const match = typeof cookie === "string" ? cookie.split(";").map((part) => part.trim()).find((part) => part.startsWith("pd_locale=")) : null;
  if (match) return match.slice("pd_locale=".length) === "zh-CN" ? "zh" : "en";
  if (typeof acceptLanguage !== "string") return "en";
  const preferred = acceptLanguage.split(",").map((entry, index) => {
    const [tag, ...params] = entry.trim().split(";");
    const quality = params.map((part) => /^\s*q\s*=\s*(0(?:\.\d+)?|1(?:\.0+)?)\s*$/i.exec(part)).find(Boolean);
    return { tag: tag.toLowerCase(), q: quality ? Number(quality[1]) : 1, index };
  }).filter((entry) => entry.tag && entry.q > 0).sort((a, b) => b.q - a.q || a.index - b.index)[0];
  return preferred?.tag === "zh" || preferred?.tag.startsWith("zh-") ? "zh" : "en";
}

